    public static function svg(string $name, string $class = '', int|float $strokeWidth = 2): string
    {
        $tpl = self::SVG[$name] ?? throw new InvalidArgumentException("Unknown icon {$name}");

        return str_replace(
            [' __CLASS__"', '__SW__'],
            [$class === '' ? '"' : ' '.e($class).'"', (string) $strokeWidth],
            $tpl,
        );
    }

    public static function has(string $name): bool
    {
        return isset(self::SVG[$name]);
    }
